    local function VM_Ill0O(d, k, m)
        local R_0l01O = {}
        local c_key = k
        local char = string.char
        local insert = table.insert
        
        -- Virtual Machine Loop
        for idx = 1, #d do
            local val = d[idx]
            -- Decodificacao Rolling Key
            local dec = (val / m) - c_key
            
            -- Anti-Crash Mobile (Garante byte valido)
            dec = dec % 256
            
            insert(R_0l01O, char(dec))
            
            -- Atualiza a chave para o proximo (Rolling)
            c_key = (c_key + 13) % 150
        end
        return table.concat(R_0l01O)
    end

    -- Execution Guard
    local F_IO10O = loadstring(VM_Ill0O(B_Ol0OlOII, 79, 5))
    if F_IO10O then
        F_IO10O(...)
    end
end)(...)
